import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  FiActivity, FiArrowUpRight, FiBarChart2, FiBookOpen, FiClock, FiImage,
  FiMessageSquare, FiRefreshCw, FiSettings, FiShield, FiUsers, FiVideo,
  FiTrendingUp, FiPlus, FiBriefcase, FiUserCheck, FiDollarSign, FiChevronRight
} from 'react-icons/fi';
import { useNavigate } from 'react-router-dom';

import api from '../../services/api';
import { useLanguage } from '../../contexts/LanguageContext';

const endpoints = {
  courses: '/api/courses/',
  messages: '/api/contact/',
  videos: '/api/videos/',
  gallery: '/api/gallery/',
  users: '/api/admin/users',
};

const getCount = (result) => (
  result.status === 'fulfilled' && Array.isArray(result.value.data)
    ? result.value.data.length
    : (result.status === 'fulfilled' && typeof result.value.data?.total === 'number' ? result.value.data.total : 0)
);

const AdminDashboard = () => {
  const navigate = useNavigate();
  const { t, language } = useLanguage();
  const isKhmer = language === 'km' || language === 'kh';

  const [stats, setStats] = useState({ courses: 0, messages: 0, videos: 0, gallery: 0, users: 0 });
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [lastUpdated, setLastUpdated] = useState(new Date());
  const [showQuickMenu, setShowQuickMenu] = useState(false);

  // Active tooltip state for interactive charts
  const [activeBar, setActiveBar] = useState(null);
  const [activeMonthPoint, setActiveMonthPoint] = useState(null);

  const fetchStats = useCallback(async (isRefresh = false) => {
    isRefresh ? setRefreshing(true) : setLoading(true);
    const entries = Object.entries(endpoints);
    const results = await Promise.allSettled(entries.map(([, url]) => api.get(url)));
    const nextStats = {};
    results.forEach((result, index) => { nextStats[entries[index][0]] = getCount(result); });
    setStats(nextStats);
    setLastUpdated(new Date());
    setLoading(false);
    setRefreshing(false);
  }, []);

  useEffect(() => {
    fetchStats();
  }, [fetchStats]);

  // Top Stat Cards matching image 1
  const topStats = useMemo(() => [
    {
      id: 'admin',
      count: `${Math.max(stats.users || 0, 3)}+`,
      label: isKhmer ? 'អ្នកគ្រប់គ្រងសរុប' : 'Total Admin',
      sublabel: 'Total Admin',
      gradient: 'from-[#3B82F6] via-[#2563EB] to-[#1D4ED8]',
      icon: FiShield,
      path: '/settings',
    },
